text:
{
  "title_novice": "Риф: растёт быстрее осадков вокруг",
  "summary": [
    {"text": "Риф — сложное карбонатное тело, сложенное остатками организмов и продуктами их разрушения.", "claims": ["c1", "c2"]},
    {"text": "Он растёт быстрее, чем накапливаются окружающие осадки, поэтому возвышается над ними.", "claims": ["c3a", "c3b"]},
    {"text": "В главе речь идёт о рифах в узком смысле — тех, что важны для нефтяников.", "claims": ["c4", "c5"]}
  ],
  "claims": [
    {"key": "c1", "text": "Риф возникает из жизнедеятельности колониальных или нарастающих организмов.", "kind": "observation", "unit_id": "u-201-78a465", "page": 201, "quote": "Рифы – это сложные геологические образования, возникающие в результате жизнедеятельности колониальных или нарастающих организмов", "numbers": [], "question": null},
    {"key": "c2", "text": "Риф — карбонатный массив, сложенный по крайней мере частично остатками организмов и продуктами их разрушения.", "kind": "observation", "unit_id": "u-201-78a465", "page": 201, "quote": "представляющие собой карбонатный массив, сложенный, по крайней мере частично, остатками организмов и продуктов их разрушения", "numbers": [], "question": null},
    {"key": "c3a", "text": "Условие роста: скорость роста рифа больше скорости накопления окружающих осадков.", "kind": "assumption", "unit_id": "u-201-78a465", "page": 201, "quote": "Поскольку скорость роста рифа превышает скорость накопления окружающих осадков", "numbers": [], "question": null},
    {"key": "c3b", "text": "Следствие: мощность рифа больше мощности синхронных отложений, и риф возвышается над ними.", "kind": "inference", "unit_id": "u-201-78a465", "page": 201, "quote": "его мощность больше мощности синхронных отложений и он возвышается над ними", "numbers": [], "question": null},
    {"key": "c4", "text": "Для нефтяников наибольший интерес представляют рифы в узком буквальном смысле слова.", "kind": "assumption", "unit_id": "u-201-d31fcf", "page": 201, "quote": "Естественно, что для геологов-нефтяников наибольший интерес представляют рифы в узком буквальном смысле этого слова.", "numbers": [], "question": null},
    {"key": "c5", "text": "Глава описывает в первую очередь строение резервуаров рифов и частично их ловушки.", "kind": "observation", "unit_id": "u-201-d31fcf", "page": 201, "quote": "Именно они, точнее строение их резервуаров и частично ловушек, описаны в настоящей работе.", "numbers": [], "question": null},
    {"key": "c6", "text": "Подробности о геологии рифов и их нефтегазоносности даны в работах Ильина и Фортунатовой.", "kind": "observation", "unit_id": "u-201-d31fcf", "page": 201, "quote": "Более подробные сведения о геологии рифов и их нефтегазоносности приведены в работах В.Д. Ильина и Н.К. Фортунатовой", "numbers": [], "question": null},
    {"key": "c7", "text": "Глава также ссылается на работы Кузнецова и на специальные сборники.", "kind": "observation", "unit_id": "u-202-c79c3c", "page": 202, "quote": "[1988], В.Г. Кузнецова [1978, 1992], специальных сборниках [Ископаемые..., 1975, Литология..., 1975, Методы..., 1983] и др.", "numbers": ["1988", "1978", "1992", "1975", "1983"], "question": null}
  ],
  "mechanism": [
    {"text": "Риф строят живые организмы, которые растут колониями или нарастают друг на друга.", "claims": ["c1"], "hypothesis": false},
    {"text": "Остатки этих организмов и продукты их разрушения образуют карбонатный массив.", "claims": ["c2"], "hypothesis": false},
    {"text": "Если рост рифа идёт быстрее накопления окружающих осадков, риф становится толще синхронных отложений.", "claims": ["c3a", "c3b"], "hypothesis": false},
    {"text": "Поэтому риф возвышается над окружающими отложениями.", "claims": ["c3b"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Специалист сравнивает толщину тела с толщиной одновозрастных отложений вокруг него.", "claims": [], "hypothesis": true},
    {"text": "По этой логике признак рифа: тело толще и выше одновозрастных отложений вокруг.", "claims": ["c3b"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Сравнение относительное: риф толще синхронных отложений, но числовых значений здесь нет.", "claims": ["c3b"], "hypothesis": false},
    {"text": "Состав сложен «по крайней мере частично» остатками организмов, значит, не обязательно целиком.", "claims": ["c2"], "hypothesis": false},
    {"text": "Условие роста быстрее осадков — допущение автора, на котором строится определение.", "claims": ["c3a"], "hypothesis": false},
    {"text": "Главный ограничитель: глава описывает рифы в узком буквальном смысле, а не любые карбонатные тела.", "claims": ["c4", "c5"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Литература по рифам", "text": "Глава отсылает к работам Ильина и Фортунатовой (1988), Кузнецова (1978, 1992) и к сборникам 1975 и 1983 годов.", "claims": ["c6", "c7"], "hypothesis": false},
    {"title": "Что сравнивается", "text": "Автор сравнивает две скорости: роста рифа и накопления окружающих осадков. Их числовые значения в тексте не даны.", "claims": ["c3a"], "hypothesis": false}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Условие: скорость роста рифа больше скорости накопления окружающих осадков.", "claims": ["c3a"]},
    {"text": "Следствие: мощность рифа больше мощности синхронных отложений.", "claims": ["c3b"]}
  ],
  "terms_defined": [
    {"term": "риф", "term_en": "reef", "abbr": "", "definition": "Сложное геологическое тело из карбонатных пород. Его строят колониальные или нарастающие организмы. Сложен он, по крайней мере частично, их остатками и продуктами разрушения. Растёт быстрее окружающих осадков и поэтому возвышается над ними.", "claims": ["c1", "c2", "c3a", "c3b"]}
  ],
  "terms_used": ["карбонатные отложения", "органогенная постройка", "мощность", "синхронные отложения", "биогерм", "карбонатный массив", "организмы"],
  "formulas": [],
  "tables": [],
  "figures": [
    {"label": "Рис. 10.1", "unit_id": "u-201-a3abfb (подпись)", "role": "Схема органогенных построек, включая рифы в разрезе; текст ссылается на неё при описании возвышения рифа.", "redraw": false}
  ],
