  "misconception": {
    "pack_id": null,
    "wrong": "Риф — любая карбонатная толща или любое тело из известняка.",
    "right": "Риф — карбонатный массив из остатков организмов, который растёт быстрее окружающих осадков и поэтому возвышается над ними.",
    "claims": ["c1", "c2", "c3a", "c3b"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Толщина карбонатного тела и толщина одновозрастных отложений вокруг него по разрезу.", "claims": [], "hypothesis": true},
      {"text": "Состав пород: признак того, что тело сложено остатками организмов.", "claims": ["c2"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Признак рифа: тело толще одновозрастных отложений и поднимается над ними.", "claims": ["c3b"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Толщина сама по себе не доказывает рост: нужны одновозрастные отложения для сравнения.", "claims": [], "hypothesis": true},
      {"text": "Состав не обязательно целиком биогенный: текст говорит «по крайней мере частично».", "claims": ["c2"], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Как сервис, который растёт быстрее остальной инфраструктуры и поэтому заметен на её фоне.",
    "breaks_where": "В рифе рост даёт живой организм из собственных остатков. У сервиса нет такого самовоспроизводства, а процесс идёт в геологическом времени."
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Если понять, что риф поднимается из-за роста быстрее осадков, можно отличать риф от других карбонатных тел в разрезе."
  },
  "inefficiency": {
    "inputs": [
      {"text": "Разрез с толщинами карбонатного тела и одновозрастных отложений вокруг.", "claims": [], "hypothesis": true}
    ],
    "manual_steps": [
      {"text": "Вручную сравнить толщину тела с толщиной синхронных отложений по каждой скважине или профилю.", "claims": [], "hypothesis": true}
    ],
    "judgment_points": [
      {"text": "Решить, растёт ли тело быстрее осадков, по толщинам и положению над окружающими отложениями.", "claims": [], "hypothesis": true}
    ],
    "time": [
      {"text": "Сравнение пачек одного возраста по всему разрезу занимает время.", "claims": [], "hypothesis": true}
    ],
    "typical_errors": [
      {"text": "Принять любое карбонатное тело за риф по виду или составу.", "claims": [], "hypothesis": true}
    ]
  },
